// ✅ Token nằm ngoài tầm với của JavaScript

// 1) Server set HttpOnly cookie — JS KHÔNG THỂ đọc
// app/api/auth/session/route.ts
export async function POST(res: Response) {
  const { accessToken, refreshToken } = await issueTokens();
  const response = new Response(JSON.stringify({ ok: true }));
  response.headers.append(
    'Set-Cookie',
    `access_token=${accessToken}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=900`
  );
  response.headers.append(
    'Set-Cookie',
    `refresh_token=${refreshToken}; HttpOnly; Secure; Strict; Path=/api/auth; Max-Age=604800`
  );
  return response;
}

// 2) Refresh Token Rotation: token cũ bị thu hồi ngay khi dùng
// 3) Frontend chỉ gọi /api/auth/* — không bao giờ chạm vào token

// ✅ 1) Header chặn nhúng — declarative, browser thực thi thay vì tin client JS
// next.config.mjs → async headers()
async headers() {
  return [{
    source: '/:path*',
    headers: [
      { key: 'Content-Security-Policy', value: "frame-ancestors 'none'" }, // ✅ chuẩn hiện đại
      { key: 'X-Frame-Options', value: 'DENY' }, // ✅ fallback cho browser cổ
    ],
  }];
}

// 2) Trang CẦN nhúng cho partner (widget thanh toán)? Whitelist từng origin, KHÔNG bao giờ '*'
